defmodule BB.LiveView.SyntheticCamera.Frames do
  @moduledoc """
  A short cycle of real JPEG images for the synthetic camera.

  160×120, a teal bar stepping left to right, so a working preview is
  obviously moving and a stuck one is obviously stuck. They are embedded as
  base64 rather than shipped as files so the whole synthetic camera is one
  source tree with no binaries to licence and no `priv` to resolve.
  """

  @encoded [
    "",
    "",
    "",
    "",
    "",
    ""
  ]

  @frames Enum.map(@encoded, &Base.decode64!/1)
  @count length(@frames)

  @doc "The number of distinct frames in the cycle."
  @spec count() :: pos_integer
  def count, do: @count

  @doc "The frame at `index`, wrapping around the cycle."
  @spec at(non_neg_integer) :: binary
  def at(index), do: Enum.at(@frames, rem(index, @count))
end
